            new Quote { Id = Source, Text = "Seseorang tidak selalu lahir dengan keberanian, tapi seseorang lahir dengan potensinya masing-masing. Tanpa keberanian, kita tidak bisa berbuat baik dengan konsisten. Kita tidak bisa menjadi baik, benar, murah hati, dermawan, atau jujur.", Author = "Maya Angelou" },
